python3 -c "
from collections import deque
from itertools import islice

def consume(iterator, n=None):
    if n is None:
        list(iterator)
    else:
        next(islice(iterator, n, n), None)

class seekable_v8:
    def __init__(self, iterable, maxlen=None):
        self._source = iter(iterable)
        if maxlen is None:
            self._cache = []
        else:
            self._cache = deque([], maxlen)
        self._index = None
        self._last_yielded = -1
        self._in_seek_mode = False

    def __iter__(self):
        return self

    def __next__(self):
        if self._index is not None:
            try:
                item = self._cache[self._index]
            except IndexError:
                self._index = None
            else:
                if not self._in_seek_mode:
                    self._last_yielded = self._index
                self._index += 1
                return item

        item = next(self._source)
        idx = len(self._cache)
        self._cache.append(item)
        if not self._in_seek_mode:
            self._last_yielded = idx
        return item

    def seek(self, index):
        self._in_seek_mode = True
        self._index = index
        remainder = index - len(self._cache)
        if remainder > 0:
            consume(self, remainder)
        self._in_seek_mode = False

    def relative_seek(self, offset):
        new_pos = self._last_yielded + 1 + offset
        if new_pos < 0:
            raise IndexError('Cannot seek before start')
        self.seek(new_pos)

it = seekable_v8((str(n) for n in range(20)))
print(f'next: {next(it)}, {next(it)}, {next(it)}')
print(f'_last_yielded={it._last_yielded}')
it.relative_seek(1)
print(f'After relative_seek(1): _last_yielded={it._last_yielded}')
print(f'next: {next(it)}')
print(f'_last_yielded={it._last_yielded}')
it.relative_seek(-2)
print(f'After relative_seek(-2): _last_yielded={it._last_yielded}')
print(f'next: {next(it)}')
